struct Event { Colleague* sender; std::string kind; };
struct Mediator {                       // the hub interface
  virtual void notify(const Event&) = 0;
  virtual ~Mediator() = default;
};
struct Colleague {                      // participants know only the hub
  explicit Colleague(Mediator& m) : hub(m) {}
  virtual ~Colleague() = default;
protected:
  Mediator& hub;
};
struct Button : Colleague { void click() { hub.notify({this, "click"}); } };

