struct Hub {
  boost::signals2::signal<void(const Event&)> onEvent;
  void notify(const Event& e) { onEvent(e); }   // colleagues call this
};
Hub hub;
hub.onEvent.connect([&dialog](const Event& e) { dialog.route(e); });
button.clicked.connect([&hub](const Click& c) { hub.notify({&c, "click"}); });

